// Font and box metrics for one badge, in world units inside the live camera
// matrix. Badge height is identical for every label at a view, so the active
// and current badges can coordinate placement from the same metrics.
cityBadgeMetrics(label){
  const c=this.ctx,wpc=1100/(this.cityTransform.scale*this.cityCssWidth()); // world units per displayed CSS px
  const font=Math.max(16,11*wpc),gap=4*wpc,padX=8*wpc,padY=3*wpc;
  c.font=`${font}px sans-serif`;
  const measured=typeof c.measureText==='function'?Number((c.measureText(label)||{}).width):NaN;
  const textW=Number.isFinite(measured)&&measured>0?measured:Array.from(String(label)).length*font;
  return {wpc,font,gap,padX,padY,textW,bw:textW+2*padX,bh:font+2*padY};
}
// Visible world-y span after the 4-CSS-px logical margin.
cityBadgeVisibleSpan(){
  const {scale,ty}=this.cityTransform;
  const margin=4*1100/(this.cityCssWidth()*scale); // 4 CSS px in world units
  return {top:(margin-ty)/scale,bottom:(640*scale?((640-4*1100/this.cityCssWidth())-ty)/scale:0)};
}
// Current-player placement. The original above-avatar offset is kept while
// it (or a margin clamp) clears the real head; if clamping would cover the
// head/body, the badge deterministically flips to below the feet instead.
cityPlayerBadgeTop(p,m){
  const span=this.cityBadgeVisibleSpan(),bh=m.bh,gap=m.gap;
  const headTop=p.y-24,feetBottom=p.y+19;
  const above=Math.max(p.y-28-gap-bh,span.top);
  if(above>=span.top&&above+bh<=headTop)return{top:above,side:'above'};
  const below=Math.max(feetBottom+gap,span.top);
  if(below>=span.top&&below+bh<=span.bottom)return{top:below,side:'below'};
  // Unreachable on the supported canvas: deterministically keep the side
  // with more room, still anchored to the same real point.
  return headTop-span.top>=span.bottom-feetBottom?{top:above,side:'above'}:{top:below,side:'below'};
}
// Active-destination placement. Keeps the original below-marker anchor
// (above for the market); if that side would clamp across the real icon,
// the coincident avatar or the current-player badge, it flips to the
// opposite side. Coincident active/current badges stack outward from the
// anchor with a fixed 4-CSS-px gap - a local two-label rule, no engine.
cityActiveBadgeTop(place,p,m){
  const span=this.cityBadgeVisibleSpan(),bh=m.bh,gap=m.gap;
  const player=this.cityPlayerBadgeTop(p,m);
  const aligned=Math.abs(p.x-place.x)<m.bw/2+10; // horizontally coincident labels
  const limits=(side)=>{
    let high=place.y-27,low=place.y+27; // the real r27 active icon extents
    if(aligned){
      high=Math.min(high,p.y-24); // never cover the real head/hat...
      low=Math.max(low,p.y+19); // ...or the walking feet
      if(player.side==='above')high=Math.min(high,player.top);
      else low=Math.max(low,player.top+bh);
    }
    return{high,low};
  };
  const fits=(side)=>{
    const {high,low}=limits(side);
    if(side==='above'){
      let top=place.y-27-gap-bh; // original market-above offset
      if(aligned&&player.side==='above')top=Math.min(top,player.top-gap-bh); // stack outside the player badge
      if(top<span.top)top=span.top;
      return top+bh<=high?top:null; // a margin clamp is legal only while it clears the icon/avatar
    }
    let top=place.y+27+gap; // original below-marker offset
    if(aligned&&player.side==='below')top=Math.max(top,player.top+bh+gap);
    if(top+bh>span.bottom)top=span.bottom-bh;
    return top>=low?top:null;
  };
  const preferred=place.id==='market'?'above':'below';
  let top=fits(preferred);
  if(top===null)top=fits(preferred==='above'?'below':'above');
  return top;
}
// Draws one opaque-backed badge inside the live camera matrix. Returns false
// when the world anchor is off the logical canvas so callers keep the
// original clipped label; an off-screen marker is never pulled on screen.
cityLabelBadge(label,wx,wy,top,m,fill,ink){
  const c=this.ctx,tr=this.cityTransform;
  if(!tr||!(tr.scale>0)||!Number.isFinite(wx)||!Number.isFinite(wy)||!Number.isFinite(top))return false;
  const {scale,tx,ty}=tr;
  if(wx*scale+tx<0||wx*scale+tx>1100||wy*scale+ty<0||wy*scale+ty>640)return false;
  const bw=m.bw,bh=m.bh;
  const margin=4*1100/this.cityCssWidth(); // 4 CSS px expressed in logical canvas units
  let cx=wx;
  const leftLog=(cx-bw/2)*scale+tx,rightLog=(cx+bw/2)*scale+tx;
  if(leftLog<margin)cx+=(margin-leftLog)/scale;else if(rightLog>1100-margin)cx-=(rightLog-(1100-margin))/scale;
  c.fillStyle=fill;c.fillRect(cx-bw/2,top,bw,bh);
  c.font=`${m.font}px sans-serif`;c.fillStyle=ink;c.textAlign='center';c.fillText(label,cx,top+m.padY+m.font*0.8);
  return true;
}

